// Complete Google OAuth callback (PKCE is the recommended Supabase flow).
(async()=>{const hash=new URLSearchParams(location.hash.replace(/^#/,""));const query=new URLSearchParams(location.search);const oauthError=query.get("error_description")||query.get("error")||hash.get("error_description")||hash.get("error");if(oauthError){history.replaceState(null,"",location.pathname);formError="Google sign-in failed: "+oauthError.replace(/\+/g," ").slice(0,240);authView="welcome";render();return;}const code=query.get("code");const access=hash.get("access_token")||query.get("access_token");if(!code&&!access)return;try{formError="Completing Google sign-in…";authView="welcome";render();let tokenValue=access;if(code){const {createClient}=await import("https://esm.sh/@supabase/supabase-js@2");const sb=createClient(SUPABASE_URL,SUPABASE_KEY,{auth:{flowType:"pkce",persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}});const {data,error}=await sb.auth.exchangeCodeForSession(code);if(error)throw error;tokenValue=data.session?.access_token;if(!tokenValue)throw Error("Google callback did not return a valid session.");}googleAccessToken=tokenValue;if(!tokenValue)throw Error("No Google access token was received. Please try again.");const out=await api("google_auth",{google_access_token:tokenValue});history.replaceState(null,"",location.pathname);if(out.session_token){session=out.session_token;accountUser=out.user;localStorage.setItem("tm_session",session);localStorage.setItem("tm_user",JSON.stringify(accountUser));localStorage.removeItem("tm_guest");guest=false;authView="welcome";activePage="home";}else if(out.needs_profile){googleProfile=out.google_user;authView="google_profile";}else throw Error("Google sign-in response was incomplete.");render();}catch(err){history.replaceState(null,"",location.pathname);googleAccessToken=null;formError="Google sign-in failed: "+(err.message||String(err));authView="welcome";render();}})();
(function(){let sx=0,sy=0,tracking=false;document.addEventListener("touchstart",e=>{if(!document.body.classList.contains("tm-chat-open")||e.touches?.length!==1)return;const target=e.target;if(!target.closest(".chat-fullscreen")||target.closest("button,input,textarea,select,[contenteditable=true],.chat-settings-panel"))return;const t=e.touches[0];sx=t.clientX;sy=t.clientY;tracking=true;},{passive:true});document.addEventListener("touchmove",e=>{if(!tracking||!e.touches?.length)return;const t=e.touches[0];if(Math.abs(t.clientY-sy)>Math.abs(t.clientX-sx)*1.2&&Math.abs(t.clientY-sy)>18)tracking=false;},{passive:true});document.addEventListener("touchend",e=>{if(!tracking||!e.changedTouches?.length)return;tracking=false;const t=e.changedTouches[0],dx=t.clientX-sx,dy=t.clientY-sy;if(dx>72&&dx>Math.abs(dy)*1.25){const back=app.querySelector("[data-chat-back]");if(back)back.click();}},{passive:true});document.addEventListener("touchcancel",()=>{tracking=false;},{passive:true});})();
